import { adopt } from "alchemy/AdoptPolicy";
import * as Cloudflare from "alchemy/Cloudflare";
import { renamedFrom } from "alchemy/Rename";
import { retain } from "alchemy/RemovalPolicy";
import * as Array from "effect/Array";
import * as Effect from "effect/Effect";
import * as Function from "effect/Function";
import * as Option from "effect/Option";
import { HostName } from "../schemas";

/**
 * The old zone keeps its existing identity and settings. The purchased Common
 * Practice zone gets separate resource names; both registered zones are adopted
 * from the verified account and retained on removal.
 */
// Keep the old registered domain available only for redirects and existing API clients.
export const legacyZoneName = HostName.make("departmentofagenticwork.com");
export const legacyRedirectHostName = HostName.make("www.departmentofagenticwork.com");
const legacyZoneResourceName = "CommonPracticeLegacyZone";
export const commonPracticeZoneName = HostName.make("withcommonpractice.com");
export const commonPracticeRedirectHostName = HostName.make("www.withcommonpractice.com");

/**
 * Zone settings, one Alchemy resource each. TLS 1.3 is on with a TLS 1.2 minimum (a 1.3
 * minimum would refuse TLS 1.2 clients, including some crawlers). Browser Integrity Check
 * is off because it answers default script user agents with Cloudflare error 1010, and
 * the lowest challenge level keeps IP-reputation challenges to a minimum.
 */
export const zoneSettings = [
  { resource: "CommonPracticeLegacyTls13", settingId: "tls_1_3", value: "on" },
  { resource: "CommonPracticeLegacyMinimumTlsVersion", settingId: "min_tls_version", value: "1.2" },
  {
    resource: "CommonPracticeLegacyBrowserIntegrityCheck",
    settingId: "browser_check",
    value: "off",
  },
  {
    resource: "CommonPracticeLegacySecurityLevel",
    settingId: "security_level",
    value: "essentially_off",
  },
  { resource: "CommonPracticeLegacyAlwaysUseHttps", settingId: "always_use_https", value: "on" },
] as const satisfies readonly {
  readonly resource: string;
  readonly settingId: Cloudflare.Zone.SettingId;
  readonly value: string;
}[];

/**
 * A bot policy that bans no user agent: no Bot Fight Mode, no AI-bot blocking or link maze,
 * no content-bot blocking, and no Cloudflare-managed robots.txt prepended to ours.
 */
export const botPolicy = {
  fightMode: false,
  aiBotsProtection: "disabled",
  crawlerProtection: "disabled",
  contentBotsProtection: "disabled",
  isRobotsTxtManaged: false,
} as const satisfies Cloudflare.BotManagement.Settings;

/**
 * These exact zones were read back from the account before the cutover. Leave the
 * shared zone override out: native Alchemy resolves each hostname's own zone.
 * A single override would incorrectly place the old hosts in the new zone.
 */
export const websiteDomain = {
  name: commonPracticeZoneName,
  redirects: [commonPracticeRedirectHostName, legacyZoneName, legacyRedirectHostName],
} satisfies Cloudflare.WorkerDomainConfig;

/** Keep the old API hostname serving the same Worker, including native MCP POST requests. */
export const apiDomain = {
  name: HostName.make("api.withcommonpractice.com"),
  aliases: [HostName.make("api.departmentofagenticwork.com")],
} satisfies Cloudflare.WorkerDomainConfig;

export const apiHosting = <Zone>(zone: Option.Option<Zone>) =>
  Option.match(zone, {
    onNone: () => ({}),
    onSome: () => ({ domain: apiDomain }),
  });

/**
 * Production serves its custom domain only. Other stages use their own stable
 * workers.dev address; neither needs additional version-preview addresses.
 */
export const websiteHosting = <Zone>(zone: Option.Option<Zone>) =>
  Option.match(zone, {
    onNone: () => ({ workersDev: { enabled: true, previewsEnabled: false } }),
    onSome: () => ({
      domain: websiteDomain,
      workersDev: false,
    }),
  });

/**
 * Declares the adopted zone, its settings, DNSSEC and its bot policy, all retained on
 * removal, and returns the zone for the Website's custom domain.
 */
const declareConfiguredZone = Effect.fn("Website.declareConfiguredZone")(function* ({
  name,
  resource,
  settingsPrefix,
}: Readonly<{
  name: HostName;
  resource: "CommonPracticeLegacyZone" | "CommonPracticeZone";
  settingsPrefix: "CommonPracticeLegacy" | "CommonPractice";
}>) {
  const renameLegacy =
    (suffix: string) =>
    <A, E, R>(declaration: Effect.Effect<A, E, R>) => {
      if (settingsPrefix === "CommonPracticeLegacy") {
        return declaration.pipe(renamedFrom(`Daw${suffix}`));
      }
      return declaration;
    };
  const zone = yield* Cloudflare.Zone.Zone(resource, { name }).pipe(
    adopt(true),
    retain(),
    renameLegacy("Zone"),
  );
  yield* Function.pipe(
    zoneSettings,
    Array.map(({ resource: settingResource, settingId, value }) => {
      const suffix = settingResource.replace(/^CommonPracticeLegacy/u, "");
      return Cloudflare.Zone.Setting(`${settingsPrefix}${suffix}`, {
        zoneId: zone.zoneId,
        settingId,
        value,
      }).pipe(retain(), renameLegacy(suffix));
    }),
    Effect.all,
  );
  yield* Cloudflare.DNS.Dnssec(`${settingsPrefix}Dnssec`, {
    zoneId: zone.zoneId,
    status: "active",
  }).pipe(retain(), renameLegacy("Dnssec"));
  yield* Cloudflare.BotManagement.BotManagement(`${settingsPrefix}BotManagement`, {
    zoneId: zone.zoneId,
    ...botPolicy,
  }).pipe(retain(), renameLegacy("BotManagement"));
  return zone;
});

/** Rename the old zone records without replacing either registered domain. */
export const declareZone = Effect.fn("Website.declareZone")(function* () {
  yield* declareConfiguredZone({
    name: legacyZoneName,
    resource: legacyZoneResourceName,
    settingsPrefix: "CommonPracticeLegacy",
  });
  return yield* declareConfiguredZone({
    name: commonPracticeZoneName,
    resource: "CommonPracticeZone",
    settingsPrefix: "CommonPractice",
  });
});
